SET XACT_ABORT ON;
BEGIN TRAN;
UPDATE dbo.MonHoc SET TenMon=N'Toán Học' WHERE TenMon=N'Toán' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Toán Học' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'Ngữ Văn' WHERE TenMon=N'Ngữ văn' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Ngữ Văn' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'Lịch Sử' WHERE TenMon=N'Lịch sử' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Lịch Sử' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'Địa Lý' WHERE TenMon=N'Địa lý' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Địa Lý' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'Hóa Học' WHERE TenMon=N'Hóa học' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Hóa Học' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'Vật Lý' WHERE TenMon=N'Vật lý' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'Vật Lý' AND other.Id<>dbo.MonHoc.Id);
UPDATE dbo.MonHoc SET TenMon=N'GDCD' WHERE TenMon=N'Giáo dục công dân' AND NOT EXISTS(SELECT 1 FROM dbo.MonHoc other WHERE other.TenMon=N'GDCD' AND other.Id<>dbo.MonHoc.Id);
