INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'Lịch Sử',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'Lịch Sử');
INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'Địa Lý',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'Địa Lý');
INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'Sinh học',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'Sinh học');
INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'Hóa Học',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'Hóa Học');
INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'Vật Lý',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'Vật Lý');
INSERT dbo.MonHoc(TenMon,DangSuDung) SELECT N'GDCD',1 WHERE NOT EXISTS(SELECT 1 FROM dbo.MonHoc WHERE TenMon=N'GDCD');
COMMIT;
